// ignore_for_file: unused_element, unnecessary_cast


class NetworkBridge {
  /// Sets the delay for bridge network operations, affecting how quickly packets are processed.
  final String? delay;
  /// Configures how MAC addresses are managed within the bridge, influencing how traffic is controlled.
  final String? macTableManager;
  /// Bridge name (generated by libvirt if not specified)
  final String? name;
  /// Configures Spanning Tree Protocol (STP) for the bridge, controlling the avoidance of loops in the network.
  final String? stp;
  /// Sets the zone attribute for the bridge, categorizing it within defined networking scopes.
  final String? zone;

  /// Creates a new [NetworkBridge].
  /// [delay] Sets the delay for bridge network operations, affecting how quickly packets are processed.
  /// [macTableManager] Configures how MAC addresses are managed within the bridge, influencing how traffic is controlled.
  /// [name] Bridge name (generated by libvirt if not specified)
  /// [stp] Configures Spanning Tree Protocol (STP) for the bridge, controlling the avoidance of loops in the network.
  /// [zone] Sets the zone attribute for the bridge, categorizing it within defined networking scopes.
  NetworkBridge({
    this.delay,
    this.macTableManager,
    this.name,
    this.stp,
    this.zone,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'delay': ?delay,
      'macTableManager': ?macTableManager,
      'name': ?name,
      'stp': ?stp,
      'zone': ?zone,
    };
  }

  factory NetworkBridge.fromMap(Map<String, dynamic> map) {
    return NetworkBridge(
      delay: map['delay'] == null ? null : map['delay'] as String,
      macTableManager: map['macTableManager'] == null ? null : map['macTableManager'] as String,
      name: map['name'] == null ? null : map['name'] as String,
      stp: map['stp'] == null ? null : map['stp'] as String,
      zone: map['zone'] == null ? null : map['zone'] as String,
    );
  }
}

